//! Versioned built-in module for a database published with only a container.
//!
//! This real Wasm program declares container configuration's environment schema
//! and hosted_auth_v1, with no user tables or callable functions. Database
//! initialization, system tables, subscriptions, and migration use the normal
//! host. Verification compares exact generated bytes before trusting its origin.

use spacetimedb_datastore::{system_tables::ModuleKind, traits::Program};
use spacetimedb_lib::deployment::{system_empty, SystemEmptyModule};
use spacetimedb_lib::environment::EnvironmentSchema;

pub const VERSION: u32 = system_empty::VERSION;

/// Return the exact bundled program for a recognized system module version.
/// Unknown versions fail closed instead of silently selecting the latest one.
pub fn program(version: u32) -> Option<Program> {
    (version == VERSION).then(|| Program {
        hash: system_empty::empty().descriptor.program_hash,
        bytes: system_empty::empty().bytes.clone(),
        kind: ModuleKind::WASM,
    })
}

/// Validate a system-empty deployment against immutable platform bytes, not
/// against an empty-looking schema supplied by a publisher or a claimed hash.
pub fn matches_program(descriptor: &SystemEmptyModule, candidate: &Program) -> bool {
    candidate.kind == ModuleKind::WASM
        && candidate.hash == descriptor.program_hash
        && system_empty::verify(descriptor, &candidate.bytes).is_ok()
}

pub fn declared_program(environment: &EnvironmentSchema) -> Result<Program, system_empty::InvalidSystemModule> {
    let generated = system_empty::generate(environment)?;
    Ok(Program {
        hash: generated.descriptor.program_hash,
        bytes: generated.bytes,
        kind: ModuleKind::WASM,
    })
}

